        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "antigravity",
        "1.0.0",
        "Google Antigravity SDK provider — Vertex AI Gemini models, OAuth auth, structured output, OSCAL compliance routing",
        &root,
    )
}

