    /// Stop a unit (resolves type at runtime).
    async fn stop(&self, unit: &str) -> zbus::Result<(bool, String)>;
    /// Restart a unit.
    async fn restart(&self, unit: &str) -> zbus::Result<(bool, String)>;
    /// Reload a unit.
