//! Zeroclaw route helpers backed by the D-Bus projection cache.

use anyhow::{bail, Result};
use simd_json::prelude::*;

use crate::projection_client::ProjectionCache;

#[derive(Debug, Clone)]
pub struct ZeroclawRoute {
    pub provider: String,
    pub upstream_provider: String,
    pub transport: Option<String>,
    pub model: String,
    pub hint: Option<String>,
    pub kind: Option<String>,
    pub status: String,
    pub available: bool,
    pub status_reason: Option<String>,
    pub source: Option<String>,
}

impl ZeroclawRoute {
    fn from_value(value: &simd_json::OwnedValue) -> Option<Self> {
        let model = value.get("model")?.as_str()?.to_string();
        let provider = value
            .get("provider")
            .and_then(|v| v.as_str())
            .unwrap_or("zeroclaw")
            .to_string();
        let upstream_provider = value
            .get("upstream_provider")
            .and_then(|v| v.as_str())
            .unwrap_or(&provider)
            .to_string();
        let status = value
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("declared")
            .to_string();
        let available = value
            .get("available")
            .and_then(|v| v.as_bool())
            .unwrap_or_else(|| status == "available");

        Some(Self {
            provider,
            upstream_provider,
            transport: value
                .get("transport")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            model,
            hint: value
                .get("hint")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            kind: value
                .get("kind")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            status,
            available,
            status_reason: value
                .get("status_reason")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            source: value
                .get("source")
                .and_then(|v| v.as_str())
                .map(str::to_string),
        })
    }
}

pub async fn routes(cache: &ProjectionCache) -> Option<Vec<ZeroclawRoute>> {
    let zeroclaw = crate::projection_client::get_projection(cache, "zeroclaw").await?;
    let route_values = zeroclaw.get("model_routes")?.as_array()?;
    Some(
        route_values
            .iter()
            .filter_map(ZeroclawRoute::from_value)
            .collect(),
    )
}

pub async fn route_for_model(cache: &ProjectionCache, model: &str) -> Option<ZeroclawRoute> {
    routes(cache)
        .await?
        .into_iter()
        .find(|route| route.model == model)
}

pub async fn ensure_model_available(cache: &ProjectionCache, model: &str) -> Result<()> {
    if let Some(route) = route_for_model(cache, model).await {
        if !route.available {
            let reason = route
                .status_reason
                .unwrap_or_else(|| "route is not available".to_string());
            bail!(
                "Zeroclaw route '{}' is {} but not available: {}",
                model,
                route.status,
                reason
            );
        }
    }

    Ok(())
}
//! Chat API routes

use axum::{extract::Extension, http::StatusCode, response::IntoResponse, Json};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tracing::{error, info};

use crate::state::AppState;
use op_llm::{ChatMessage, ProviderType};

/// Chat message request
#[derive(Debug, Deserialize)]
pub struct ChatRequest {
    pub message: String,
    #[serde(default)]
    pub provider: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
    #[serde(default)]
    pub conversation_id: Option<String>,
}

/// Chat message response
#[derive(Debug, Serialize)]
pub struct ChatResponse {
    pub content: String,
    pub provider: String,
    pub model: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tools_used: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

/// POST /api/chat - Send a chat message
pub async fn chat_message(
    Extension(state): Extension<Arc<AppState>>,
    Json(req): Json<ChatRequest>,
) -> impl IntoResponse {
    info!("Chat request: {} chars", req.message.len());

    // Determine provider and model
    let provider_type = if let Some(ref p) = req.provider {
        match p.parse::<ProviderType>() {
            Ok(pt) => Some(pt),
            Err(_) => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(ChatResponse {
                        content: String::new(),
                        provider: p.clone(),
                        model: String::new(),
                        tools_used: None,
                        error: Some(format!("Unknown provider: {}", p)),
                    }),
                );
            }
        }
    } else {
        None
    };

    // Build messages
    let messages = vec![
        ChatMessage::system("You are a helpful AI assistant integrated with op-dbus, a system management tool. You can help with system administration, code, and general questions."),
        ChatMessage::user(&req.message),
    ];

    let selected_model = match req.model.clone() {
        Some(model) => model,
        None => state.chat_manager.current_model().await,
    };
    if let Err(e) =
        crate::zeroclaw_routes::ensure_model_available(&state.projection_cache, &selected_model)
            .await
    {
        return (
            StatusCode::CONFLICT,
            Json(ChatResponse {
                content: String::new(),
                provider: req.provider.unwrap_or_else(|| "zeroclaw".to_string()),
                model: selected_model,
                tools_used: None,
                error: Some(e.to_string()),
            }),
        );
    }

    // Send to LLM
    let result = if let Some(pt) = provider_type.as_ref() {
        if !state.chat_manager.has_provider(pt) {
            return (
                StatusCode::CONFLICT,
                Json(ChatResponse {
                    content: String::new(),
                    provider: pt.to_string(),
                    model: selected_model,
                    tools_used: None,
                    error: Some(format!("Provider {} is not available", pt)),
                }),
            );
        }
        state
            .chat_manager
            .chat_with(pt, &selected_model, messages)
            .await
    } else if req.model.is_some() {
        let Some(route) =
            crate::zeroclaw_routes::route_for_model(&state.projection_cache, &selected_model).await
        else {
            return (
                StatusCode::CONFLICT,
                Json(ChatResponse {
                    content: String::new(),
                    provider: "zeroclaw".to_string(),
                    model: selected_model,
                    tools_used: None,
                    error: Some("Model is not routed by Zeroclaw".to_string()),
                }),
            );
        };
        let provider_type = match route.upstream_provider.parse::<ProviderType>() {
            Ok(provider_type) if state.chat_manager.has_provider(&provider_type) => provider_type,
            Ok(provider_type) => {
                return (
                    StatusCode::CONFLICT,
                    Json(ChatResponse {
                        content: String::new(),
                        provider: provider_type.to_string(),
                        model: selected_model,
                        tools_used: None,
                        error: Some(format!("Provider {} is not available", provider_type)),
                    }),
                );
            }
            Err(_) => {
                return (
                    StatusCode::CONFLICT,
                    Json(ChatResponse {
                        content: String::new(),
                        provider: route.upstream_provider,
                        model: selected_model,
                        tools_used: None,
                        error: Some("Route upstream provider is unknown".to_string()),
                    }),
                );
            }
        };
        state
            .chat_manager
            .chat_with(&provider_type, &selected_model, messages)
            .await
    } else {
        // Use current provider and model
        state.chat_manager.chat(messages).await
    };

    match result {
        Ok(response) => {
            info!(
                "Chat response from {}/{}: {} chars",
                response.provider,
                response.model,
                response.message.content.len()
            );

            (
                StatusCode::OK,
                Json(ChatResponse {
                    content: response.message.content,
                    provider: response.provider,
                    model: response.model,
                    tools_used: None,
                    error: None,
                }),
            )
        }
        Err(e) => {
            error!("Chat error: {}", e);

            let current_provider = state.chat_manager.current_provider().await;
            let current_model = state.chat_manager.current_model().await;

            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(ChatResponse {
                    content: String::new(),
                    provider: provider_type
                        .map(|p| p.to_string())
                        .unwrap_or(current_provider.to_string()),
                    model: req.model.unwrap_or(current_model),
                    tools_used: None,
                    error: Some(e.to_string()),
                }),
            )
        }
    }
}
//! LLM API routes for provider and model management

use axum::{
    extract::{Extension, Query},
    http::StatusCode,
    response::IntoResponse,
    Json,
};
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use std::sync::Arc;
use tracing::error;

use crate::state::AppState;
use op_llm::ProviderType;

/// LLM status response
#[derive(Debug, Serialize)]
pub struct LlmStatusResponse {
    pub provider: String,
    pub model: String,
    pub model_non_sandboxed: bool,
    pub available_providers: Vec<String>,
}

/// Model list response
#[derive(Debug, Serialize)]
pub struct ModelsResponse {
    pub provider: String,
    pub models: Vec<ModelInfo>,
}

#[derive(Debug, Serialize)]
pub struct ModelInfo {
    pub id: String,
    pub name: String,
    pub description: Option<String>,
    pub available: bool,
    pub provider: Option<String>,
    pub upstream_provider: Option<String>,
    pub transport: Option<String>,
    pub status: Option<String>,
    pub route_hint: Option<String>,
    pub route_kind: Option<String>,
    pub status_reason: Option<String>,
    pub source: Option<String>,
}

/// Query params for models endpoint
#[derive(Debug, Deserialize)]
pub struct ModelsQuery {
    pub provider: Option<String>,
}

/// GET /api/llm/status - Get current LLM status
pub async fn get_llm_status(Extension(state): Extension<Arc<AppState>>) -> impl IntoResponse {
    let status = state.chat_manager.get_status().await;

    Json(LlmStatusResponse {
        provider: status["provider"].as_str().unwrap_or("unknown").to_string(),
        model: status["model"].as_str().unwrap_or("").to_string(),
        model_non_sandboxed: state.chat_manager.current_model_non_sandboxed().await,
        available_providers: status["available_providers"]
            .as_array()
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default(),
    })
}

/// Build the model list from the zeroclaw plugin projection (`model_routes`).
///
/// The zeroclaw plugin is the single source of truth: its live state
/// is projected verbatim at `/org/opdbus/v1/plugins/zeroclaw`. We read it from
/// the projection cache and surface each route as a selectable model.
async fn models_from_zeroclaw(state: &AppState) -> Option<Vec<ModelInfo>> {
    let routes = crate::zeroclaw_routes::routes(&state.projection_cache).await?;

    let models: Vec<ModelInfo> = routes
        .iter()
        .map(|route| {
            let description = match route.hint.as_deref() {
                Some(h) => format!("{} · {} · {}", route.provider, h, route.status),
                None => format!("{} · {}", route.provider, route.status),
            };
            let name = match route.hint.as_deref() {
                Some(h) => format!("{} ({})", route.model, h),
                None => route.model.clone(),
            };
            ModelInfo {
                id: route.model.clone(),
                name,
                description: Some(description),
                available: route.available,
                provider: Some(route.upstream_provider.clone()),
                upstream_provider: Some(route.upstream_provider.clone()),
                transport: route.transport.clone(),
                status: Some(route.status.clone()),
                route_hint: route.hint.clone(),
                route_kind: route.kind.clone(),
                status_reason: route.status_reason.clone(),
                source: route.source.clone(),
            }
        })
        .collect();

    if models.is_empty() {
        None
    } else {
        Some(models)
    }
}

/// GET /api/llm/models - Get models for current or specified provider
pub async fn get_models(
    Extension(state): Extension<Arc<AppState>>,
    Query(query): Query<ModelsQuery>,
) -> impl IntoResponse {
    let Some(ref provider_str) = query.provider else {
        // The zeroclaw plugin projection is the default source of truth for the combined model list.
        if let Some(models) = models_from_zeroclaw(&state).await {
            return Json(ModelsResponse {
                provider: "zeroclaw".to_string(),
                models,
            })
            .into_response();
        }

        return (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(simd_json::json!({
                "error": "Zeroclaw model route projection is unavailable",
                "provider": "zeroclaw",
                "models": []
            })),
        )
            .into_response();
    };

    if provider_str == "zeroclaw" {
        if let Some(models) = models_from_zeroclaw(&state).await {
            return Json(ModelsResponse {
                provider: "zeroclaw".to_string(),
                models,
            })
            .into_response();
        }
    }

    let provider_type = match provider_str.parse::<ProviderType>() {
        Ok(pt) => pt,
        Err(_) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(simd_json::json!({ "error": format!("Unknown provider: {}", provider_str) })),
            )
                .into_response();
        }
    };

    // Check if provider is available
    if !state.chat_manager.has_provider(&provider_type) {
        return (
            StatusCode::BAD_REQUEST,
            Json(simd_json::json!({
                "error": format!("Provider {} not available. Check API key.", provider_type),
                "provider": provider_type.to_string(),
                "models": []
            })),
        )
            .into_response();
    }

    match state
        .chat_manager
        .list_models_for_provider(&provider_type)
        .await
    {
        Ok(models) => {
            let model_infos: Vec<ModelInfo> = models
                .into_iter()
                .map(|m| ModelInfo {
                    id: m.id,
                    name: m.name,
                    description: m.description,
                    available: m.available,
                    provider: Some(provider_type.to_string()),
                    upstream_provider: Some(provider_type.to_string()),
                    transport: None,
                    status: Some(
                        if m.available {
                            "available"
                        } else {
                            "unavailable"
                        }
                        .to_string(),
                    ),
                    route_hint: None,
                    route_kind: None,
                    status_reason: None,
                    source: None,
                })
                .collect();

            Json(ModelsResponse {
                provider: provider_type.to_string(),
                models: model_infos,
            })
            .into_response()
        }
        Err(e) => {
            error!("Failed to list models for {}: {}", provider_type, e);
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(simd_json::json!({
                    "error": format!("Failed to list models: {}", e),
                    "provider": provider_type.to_string(),
                    "models": []
                })),
            )
                .into_response()
        }
    }
}

