/// Reader that extracts live state from runtime plugins.
pub struct SystemPluginReader {
    /// Source identifier
    source: String,
    /// Loaded runtime plugins and their resolved schemas
    plugins: Vec<LoadedPlugin>,
}

impl std::fmt::Debug for SystemPluginReader {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let plugin_names: Vec<&str> = self
            .plugins
            .iter()
            .map(|plugin| plugin.name.as_str())
            .collect();
        f.debug_struct("SystemPluginReader")
            .field("source", &self.source)
            .field("plugins", &plugin_names)
            .finish()
    }
}

impl SystemPluginReader {
    /// Creates an empty reader when plugin bootstrap is unavailable.
    pub fn empty() -> Self {
        Self {
            source: "plugin".to_string(),
            plugins: Vec::new(),
        }
    }

    /// Creates a new SystemPluginReader backed by the default runtime plugins.
    /// Uses MemoryStore — no SQLite, zero drift. Current state = desired state.
    pub async fn new() -> Result<Self> {
        let state_store: Arc<dyn StateStore> = Arc::new(MemoryStore::new());

        let registry = DefaultPluginRegistry::new(state_store);
        let plugins = registry.load_all_plugins().await?;
        let plugins = plugins
            .into_iter()
            .map(|plugin| {
                let name = plugin.name().to_string();
                let schema = Self::plugin_owned_schema(&name, plugin.schema());

                if schema.is_none() {
                    warn!(
                        plugin_id = %name,
                        "Plugin has no PluginSchema; top-level state will be projected without plugin-specific validation"
                    );
                }

                LoadedPlugin { name, schema, plugin }
            })
            .collect::<Vec<_>>();

        info!(
            plugin_count = plugins.len(),
            "Initialized plugin projection reader"
        );

        Ok(Self {
            source: "plugin".to_string(),
            plugins,
        })
    }

    /// The schema used to validate nested plugin object projections.
    pub fn nested_object_projection_schema() -> PluginSchema {
        let read_only_string = |description: &str| FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: description.to_string(),
            default: None,
            example: None,
            constraints: Vec::new(),
            read_only: true,
            read_only_when: None,
        };

        PluginSchema::builder("plugin.object")
            .version("1.0.0")
            .category("plugin")
            .field("plugin_id", read_only_string("Owning plugin identifier"))
            .field("parent_id", read_only_string("Parent projection entity ID"))
            .field(
                "object_path",
                read_only_string("JSON pointer-like path to the nested object"),
            )
            .field(
                "value",
                FieldSchema {
                    field_type: FieldType::Any,
                    required: true,
                    description: "Nested object value mirrored from plugin state".to_string(),
                    default: None,
                    example: None,
                    constraints: Vec::new(),
                    read_only: true,
                    read_only_when: None,
                },
            )
            .build()
    }

    /// Returns all schemas required for plugin state projection.
    ///
    /// Plugin schemas are the canonical `PluginSchema` directly — no conversion:
    /// the plugin is the schema.
    pub fn projection_schemas(&self) -> Vec<PluginSchema> {
        let mut schemas = self
            .plugins
            .iter()
            .filter_map(|plugin| plugin.schema.clone())
            .collect::<Vec<_>>();
        schemas.push(Self::nested_object_projection_schema());
        schemas
    }

    /// Reads all plugin-backed projection entities asynchronously.
    pub async fn read_all_async(&self) -> Result<Vec<RawEntity>> {
        let mut entities = Vec::new();

        for plugin in &self.plugins {
            entities.extend(self.read_loaded_plugin(plugin).await?);
        }

        debug!(
            entity_count = entities.len(),
            "Read plugin projection entities"
        );
        Ok(entities)
    }

    /// Reads all projection entities for a single plugin asynchronously.
    pub async fn read_plugin_objects_async(&self, plugin_id: &str) -> Result<Vec<RawEntity>> {
        let requested_id = DefaultPluginRegistry::resolve_requested_plugin_name(plugin_id)
            .with_context(|| format!("invalid plugin request '{}'", plugin_id))?;
        let requested_plugin;
        let plugin = match self
            .plugins
            .iter()
            .find(|plugin| plugin.name == requested_id)
        {
            Some(plugin) => plugin,
            None => {
                requested_plugin = Self::load_requested_plugin(&requested_id).await?;
                &requested_plugin
            }
        };

        self.read_loaded_plugin(plugin).await
    }

    async fn load_requested_plugin(plugin_id: &str) -> Result<LoadedPlugin> {
        let state_store: Arc<dyn StateStore> = Arc::new(MemoryStore::new());
        let registry = DefaultPluginRegistry::new(state_store);
        let plugin = registry
            .load_plugin(plugin_id)
            .await
            .with_context(|| format!("failed to auto-load requested plugin '{}'", plugin_id))?;
        let name = plugin.name().to_string();
        let schema = Self::plugin_owned_schema(&name, plugin.schema());

        Ok(LoadedPlugin {
            name,
            schema,
            plugin,
        })
    }

    fn plugin_owned_schema(plugin_id: &str, schema: Option<PluginSchema>) -> Option<PluginSchema> {
        match schema {
            Some(schema) if schema.name == plugin_id => Some(schema),
            Some(schema) => {
                warn!(
                    plugin_id,
                    schema_name = %schema.name,
                    "Ignoring schema whose name does not match the owning plugin"
                );
                None
            }
            None => None,
        }
    }

    /// Reads nested object projections for a single plugin asynchronously.
    pub async fn read_nested_objects_async(
        &self,
        plugin_id: &str,
        parent_id: &str,
    ) -> Result<Vec<RawEntity>> {
        let entities = self.read_plugin_objects_async(plugin_id).await?;

        Ok(entities
            .into_iter()
            .filter(|entity| {
                entity.entity_type == "plugin.object"
                    && entity
                        .data
                        .get("parent_id")
                        .and_then(|value| value.as_str())
                        == Some(parent_id)
            })
            .collect())
//! Projection Server: pure read-through D-Bus projection of the plugin tree.
//!
//! Mounts the projected plugin tree at `org.opdbus.v1.plugins` and serves
//! each plugin's state as a `ProjectedObject` that reads 1:1 from the shm
//! projection layer (`/dev/shm/opdbus/projections/<plugin>.json`).
//!
//! The MutationEngine (the single write door) writes each plugin's full state
//! to shm on every mutation. This server mounts the tree from shm on startup
//! and exposes a `refresh()` D-Bus method on the root interface that re-reads
//! shm and syncs the tree (mount/unmount). No gRPC subscription, no polling,
//! no inotify — the tree is derived on demand.

use anyhow::{Context, Result};
use op_projection::*;
use std::collections::HashMap;
use tracing::{info, warn};
use tracing_subscriber::{EnvFilter, FmtSubscriber};

#[tokio::main]
async fn main() -> Result<()> {
    let subscriber = FmtSubscriber::builder()
        .with_env_filter(EnvFilter::from_default_env())
        .finish();
    tracing::subscriber::set_global_default(subscriber)?;

    info!("Starting Operation-DBus Projection Server (read-through)");

    // 1. Initialize Schema Engine + discover plugin schemas (writes to shm).
    let mut schema_engine = SchemaEngine::new();

    let plugin_reader = match SystemPluginReader::new().await {
        Ok(reader) => reader,
        Err(error) => {
            warn!(
                error = %error,
                "Failed to initialize plugin reader; continuing with empty schema catalog"
            );
            SystemPluginReader::empty()
        }
    };

    let projection_schemas = plugin_reader.projection_schemas();
    let schema_map: HashMap<String, PluginSchema> = projection_schemas
        .iter()
        .map(|schema| (schema.name.clone(), schema.clone()))
        .collect();

    for schema in projection_schemas {
        register_schema_if_missing(&mut schema_engine, schema)?;
    }

    info!(
        schemas = schema_engine.list_schemas().len(),
        "Schema catalog published to shm"
    );

    // 2. Initialize D-Bus server (owns org.opdbus.v1.plugins, root interface
    //    at /org/opdbus/v1/plugins is always present for introspection).
    let dbus_server = ProjectionDbusServer::new_with_schemas(schema_map.clone())
        .await
        .context("failed to start projection D-Bus server")?;

    // 3. Initial tree sync: mount from shm (mutations) then seed all known
    //    plugin roots from the schema catalog so the tree is never empty.
    dbus_server.sync_from_shm().await?;

    let known_plugins: Vec<String> = schema_map.keys().cloned().collect();
    dbus_server.seed_plugin_roots(&known_plugins).await?;

    let count = dbus_server.object_count().await;
    info!(
        objects = count,
        plugins = known_plugins.len(),
        "Initial tree sync complete"
    );

    // 4. Initialize JSON-stream server (for WebSocket clients).
    let mut stream_server = ProjectionStreamServer::new();
    stream_server.start(8082)?;

    // 5. Run forever. The tree is derived on-demand via the `refresh()` D-Bus
    //    method on the ProjectionRoot interface. No gRPC, no polling.
    info!("Projection server ready — tree syncs on refresh() D-Bus call or restart");
    tokio::signal::ctrl_c().await?;

    Ok(())
}

fn register_schema_if_missing(
    schema_engine: &mut SchemaEngine,
    schema: PluginSchema,
) -> Result<()> {
    if schema_engine.has_valid_schema(&schema.name) {
        return Ok(());
    }

    let schema_name = schema.name.clone();
    schema_engine
        .register_schema(schema)
        .with_context(|| format!("failed to register projection schema '{}'", schema_name))?;
    Ok(())
}

