fn read_live_schema_plugins() -> Vec<PluginInfo> {
    let Ok(bytes) = std::fs::read(LIVE_SCHEMA_PATH) else {
        return Vec::new();
    };
    let Ok(root) = serde_json::from_slice::<JsonValue>(&bytes) else {
        return Vec::new();
    };
    let Some(catalog) = root.as_object() else {
        return Vec::new();
    };

    catalog
        .iter()
        .filter_map(|(id, entries)| {
            let schema = first_schema_entry(entries)?;
            Some(plugin_info_from_schema(id, schema))
        })
        .collect()
}

fn read_per_plugin_schema_plugins() -> Vec<PluginInfo> {
    let Ok(entries) = std::fs::read_dir(PER_PLUGIN_SCHEMA_DIR) else {
        return Vec::new();
    };

    entries
        .filter_map(Result::ok)
        .filter_map(|entry| {
            let path = entry.path();
            if path.extension().and_then(|ext| ext.to_str()) != Some("json") {
                return None;
            }
            let id = path.file_stem()?.to_str()?.to_string();
            let bytes = std::fs::read(path).ok()?;
            let schema = serde_json::from_slice::<JsonValue>(&bytes).ok()?;
            Some(plugin_info_from_schema(&id, &schema))
        })
        .collect()
}

fn read_schema(plugin_id: &str) -> Option<(String, String, String)> {
    read_live_schema(plugin_id).or_else(|| read_per_plugin_schema(plugin_id))
}

fn read_live_schema(plugin_id: &str) -> Option<(String, String, String)> {
    let bytes = std::fs::read(LIVE_SCHEMA_PATH).ok()?;
    let root = serde_json::from_slice::<JsonValue>(&bytes).ok()?;
    let schema = root
        .as_object()?
        .get(plugin_id)?
        .as_array()
        .and_then(|items| items.first())
        .or_else(|| root.as_object()?.get(plugin_id))?;
    schema_response_from_value(schema)
}

fn read_per_plugin_schema(plugin_id: &str) -> Option<(String, String, String)> {
    let path = format!("{PER_PLUGIN_SCHEMA_DIR}/{plugin_id}.json");
    let bytes = std::fs::read(path).ok()?;
    let schema = serde_json::from_slice::<JsonValue>(&bytes).ok()?;
    schema_response_from_value(&schema)
}

fn schema_response_from_value(schema: &JsonValue) -> Option<(String, String, String)> {
    let version = schema
        .get("version")
        .and_then(JsonValue::as_str)
        .unwrap_or("1.0.0")
        .to_string();
    Some((
        serde_json::to_string(schema).ok()?,
        "operation.pluginschema+json".to_string(),
        version,
    ))
}

fn plugin_info_from_schema(id: &str, schema: &JsonValue) -> PluginInfo {
    let name = schema
        .get("name")
        .and_then(JsonValue::as_str)
        .unwrap_or(id)
        .to_string();
    let version = schema
        .get("version")
        .and_then(JsonValue::as_str)
        .unwrap_or("1.0.0")
        .to_string();
    let description = schema
        .get("description")
        .and_then(JsonValue::as_str)
        .unwrap_or("")
        .to_string();
    let mut tags = Vec::new();
    if let Some(category) = schema.get("category").and_then(JsonValue::as_str) {
        tags.push(category.to_string());
    }

    PluginInfo {
        id: id.to_string(),
        name,
        version,
        description,
        dbus_path: format!("/org/opdbus/v1/plugins/{}", id.replace('.', "/")),
        interfaces: vec!["org.opdbus.v1.Plugin".to_string()],
        tags,
    }
}

